package net.hivel.islandsrpg.data;
import net.hivel.islandsrpg.quest.QuestProgress; import net.hivel.islandsrpg.stats.StatType; import org.bukkit.configuration.file.*; import org.bukkit.entity.Player; import org.bukkit.plugin.java.JavaPlugin; import java.io.*; import java.util.*;
public class PlayerDataManager { private final JavaPlugin plugin; private final Map<UUID,PlayerData> cache=new HashMap<>(); private final File dir; public PlayerDataManager(JavaPlugin plugin){this.plugin=plugin; this.dir=new File(plugin.getDataFolder(),"playerdata"); dir.mkdirs();} public PlayerData get(Player p){return cache.computeIfAbsent(p.getUniqueId(), id -> load(p));} public PlayerData get(UUID id){return cache.get(id);} public PlayerData load(Player p){File f=new File(dir,p.getUniqueId()+".yml"); PlayerData d=new PlayerData(p.getUniqueId(),p.getName()); if(f.exists()){FileConfiguration y=YamlConfiguration.loadConfiguration(f); d.name=y.getString("name",p.getName()); d.level=y.getInt("level",1); d.xp=y.getLong("xp",0); d.money=y.getLong("money",0); d.fragments=y.getLong("fragments",0); d.statPoints=y.getInt("stat-points",0); for(StatType t:StatType.values()) d.stats.put(t,y.getInt("stats."+t.key,0)); for(String q:y.getConfigurationSection("active-quests")==null?List.<String>of():y.getConfigurationSection("active-quests").getKeys(false)) d.activeQuests.put(q,new QuestProgress(q,y.getInt("active-quests."+q))); d.completedQuests.addAll(y.getStringList("completed-quests")); loadMap(y,"kills",d.kills); loadMap(y,"boss-kills",d.bossKills); d.unlockedIslands.clear(); d.unlockedIslands.addAll(y.getStringList("unlocked-islands")); if(d.unlockedIslands.isEmpty())d.unlockedIslands.add("starter"); } cache.put(p.getUniqueId(),d); return d;} private void loadMap(FileConfiguration y,String path,Map<String,Integer> map){ if(y.getConfigurationSection(path)!=null) for(String k:y.getConfigurationSection(path).getKeys(false)) map.put(k,y.getInt(path+"."+k)); } public void save(PlayerData d){try{File f=new File(dir,d.uuid+".yml"); YamlConfiguration y=new YamlConfiguration(); y.set("uuid",d.uuid.toString()); y.set("name",d.name); y.set("level",d.level); y.set("xp",d.xp); y.set("money",d.money); y.set("fragments",d.fragments); y.set("stat-points",d.statPoints); for(var e:d.stats.entrySet()) y.set("stats."+e.getKey().key,e.getValue()); for(var e:d.activeQuests.entrySet()) y.set("active-quests."+e.getKey(),e.getValue().current()); y.set("completed-quests",new ArrayList<>(d.completedQuests)); d.kills.forEach((k,v)->y.set("kills."+k,v)); d.bossKills.forEach((k,v)->y.set("boss-kills."+k,v)); y.set("unlocked-islands",new ArrayList<>(d.unlockedIslands)); y.save(f);}catch(Exception e){plugin.getLogger().warning("Could not save playerdata: "+e.getMessage());}} public void unload(Player p){PlayerData d=cache.remove(p.getUniqueId()); if(d!=null)save(d);} public void saveAll(){cache.values().forEach(this::save);} }
